		   Feature PostFeatureModule = AddRolesAndFeaturesClass.AddFeature(new FeatureDetails() { Code = "Module", FeatureTypeCode = "MODL", IsBusinessUnitEnabled = false, ObjectTableId = PostObjectTable.Id, Tenant = 0, NameTextCodeCode = "Post.Features.PackageFeature", NameTextCodeDefaultText = "Post Package Feature", Packagable = true }, FeaturesRepository, TextCodeRepository, TenantFeatures, TextCodes,PostObjectTable,contextTenant);    
	    
